package com.salespunch360.mobile.ui.account.accounting
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.*;import androidx.compose.material.icons.Icons;import androidx.compose.material.icons.filled.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import androidx.lifecycle.compose.collectAsStateWithLifecycle;import androidx.lifecycle.viewmodel.compose.viewModel;import com.salespunch360.mobile.*;import com.salespunch360.mobile.account.*;import kotlinx.serialization.json.*
@Composable fun FinancialYearScreen(periodLocks:Boolean,padding:PaddingValues,vm:AccountAccountingViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value,years=s.data.array("financialYears").map{it.jsonObject};Column(Modifier.fillMaxSize().padding(padding).padding(16.dp)){Row{Text(if(periodLocks)"Period locks" else "Financial years",style=MaterialTheme.typography.headlineSmall,modifier=Modifier.weight(1f));IconButton(vm::load){Icon(Icons.Default.Refresh,"Refresh")};FilledIconButton({vm.editor(if(periodLocks)"period-locks" else "financial-years")}){Icon(Icons.Default.Add,"New")}};if(s.loading)LinearProgressIndicator(Modifier.fillMaxWidth());s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};LazyColumn{items(years,key={it.str("id")}){y->val lock=s.data.array("accountingPeriodLocks").map{it.jsonObject}.firstOrNull{it.str("financialYearId")==y.str("id")};ListItem(headlineContent={Text(y.str("name"))},supportingContent={Text("${y.str("startDate").take(10)} – ${y.str("endDate").take(10)}${lock?.let{" · locked through ${it.str("lockedThrough").take(10)}"}.orEmpty()}")},trailingContent={if(!periodLocks&&y.str("status")=="OPEN")TextButton({vm.editor("close:${y.str("id")}")}){Text("Close")}else Text(y.str("status"))})}}};s.editor?.let{FinancialDialog(it,years,vm::close){k,p->vm.save(k,p)}}}
@Composable private fun FinancialDialog(kind:String,years:List<JsonObject>,close:()->Unit,save:(String,JsonObject)->Unit){var name by remember{mutableStateOf("")};var from by remember{mutableStateOf("")};var to by remember{mutableStateOf("")};var year by remember{mutableStateOf(kind.substringAfter("close:",""))};var reason by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text(kind.substringBefore(':').replace('-',' '))},text={Column{if(kind=="financial-years"){OutlinedTextField(name,{name=it},label={Text("Name")});OutlinedTextField(from,{from=it},label={Text("Start date")});OutlinedTextField(to,{to=it},label={Text("End date")})}else if(kind=="period-locks"){Option("Financial year",year,years){year=it};OutlinedTextField(to,{to=it},label={Text("Lock through")});OutlinedTextField(reason,{reason=it},label={Text("Reason")})}else{Text("Closing performs server verification and permanently locks the year.");OutlinedTextField(reason,{reason=it},label={Text("Early-close reason when required")})}}},confirmButton={Button(onClick={when{kind=="financial-years"->{save("financial-years",buildJsonObject{put("name",name);put("startDate",from);put("endDate",to);put("isCurrent",true)})};kind=="period-locks"->{save("period-locks",buildJsonObject{put("financialYearId",year);put("lockedThrough",to);put("reason",reason)})};else->{save("close-year",buildJsonObject{put("financialYearId",year);put("earlyCloseReason",reason)})}}}){Text("Confirm on server")}},dismissButton={TextButton(close){Text("Cancel")}})}
